/**
 * Format a scalar parameter-alias value as an OData literal.
 *
 * Strings become string literals: wrapped in single quotes, with each embedded `'` doubled
 * (`O'Brien` becomes `'O''Brien'`), as OData requires. Without the doubling the literal ends at
 * the first `'` in the value (FetchXML with single-quoted attributes, names such as O'Brien) and
 * Dataverse answers 400. Other values (numbers, booleans, `null`) are written with `String()`.
 * The caller URL-encodes the result.
 */
export function formatAliasValue(value: unknown): string {
  return typeof value === "string" ? `'${value.replace(/'/g, "''")}'` : String(value);
}
